<div class="topline"><span>SEE THE WHOLE PICTURE</span><span>A month of small steps adds up.</span></div><header class="page-header"><div><h1>Pause. Notice your progress.</h1><p class="muted">A monthly view of your money, study, career, habits, and growth.</p></div><form class="inline" method="get" action="/insights"><label class="sr-only" for="review-month">Review month</label><input id="review-month" type="month" name="month" value="<?= e($month) ?>" required><button class="secondary">View month</button></form></header><?php require ROOT.'/app/Core/views/notices.php'; ?>
<div class="stats four"><section class="card"><p class="muted">Income / expenses</p><div class="big-number"><?= !empty($summary['money']['entries']) ? money($summary['money']['income']) : '<span class="no-data">No data yet</span>' ?></div><small><?= !empty($summary['money']['entries']) ? money($summary['money']['expenses']).' spent in '.$month : 'Record your own income and spending' ?></small></section><section class="card"><p class="muted">Completed study time</p><div class="big-number"><?= $summary['focus_minutes']>0 ? e($summary['focus_minutes']).' min' : '<span class="no-data">No data yet</span>' ?></div><small>Completed focus sessions this month</small></section><section class="card"><p class="muted">Assignments due this month</p><div class="big-number"><?= $summary['assignments']>0 ? e($summary['completed_assignments']).' / '.e($summary['assignments']) : '<span class="no-data">No data yet</span>' ?></div><small>Completed / total due</small></section><section class="card"><p class="muted">Habit check-ins</p><div class="big-number"><?= $summary['habit_checkins']>0 ? e($summary['habit_checkins']) : '<span class="no-data">No data yet</span>' ?></div><small>Check-ins recorded this month</small></section></div>
<div class="two-col"><section class="card"><h2>This month, in context</h2><dl class="summary-list"><dt>Exams scheduled</dt><dd><?= $summary['exams'] ?: 'No data yet' ?></dd><dt>Applications submitted</dt><dd><?= $summary['applications'] ?: 'No data yet' ?></dd><dt>Lessons recorded</dt><dd><?= $summary['lessons'] ?: 'No data yet' ?></dd><dt>Currently active personal goals</dt><dd><?= $summary['current_goals'] ?: 'No data yet' ?></dd></dl><p class="footnote">Monthly counts use recorded dates. Active goals are your current goal count, not a historical snapshot.</p><a class="btn secondary" href="/settings/report" hx-boost="false">Print / PDF report</a></section><section class="card"><h2>Your monthly review</h2><form class="stack" method="post" action="/insights/review"><?= csrf_field() ?><input type="hidden" name="month" value="<?= e($month) ?>"><label>Wins<textarea name="wins" rows="2" maxlength="5000"><?= e($review['wins'] ?? '') ?></textarea></label><label>Lessons<textarea name="lessons" rows="2" maxlength="5000"><?= e($review['lessons'] ?? '') ?></textarea></label><label>Next month’s focus<textarea name="focus" rows="2" maxlength="2000"><?= e($review['focus'] ?? '') ?></textarea></label><label>Month score (1–10)<input name="score" type="number" min="1" max="10" value="<?= e($review['score'] ?? '') ?>" required></label><button>Save monthly review</button></form></section></div>
<section class="card" id="alerts"><div class="section-heading"><h2>Things that need your attention</h2><span class="badge"><?= count($alerts) ?> reminders</span></div><?php if (!$alerts): ?><div class="empty"><h3>You’re up to date.</h3><p>Deadline, payment, goal, and overspending reminders appear here as you add records.</p></div><?php else: foreach ($alerts as $alert): ?><div class="task-row"><div><a href="<?= e($alert['route']) ?>"><strong><?= e($alert['title']) ?></strong></a><small><?= e($alert['body']) ?></small></div><form method="post" action="/insights/alerts/<?= e($alert['id']) ?>/dismiss"><?= csrf_field() ?><button class="quiet">Dismiss today</button></form></div><?php endforeach; endif; ?><h3>Windows notifications</h3><form method="post" action="/insights/notifications" class="stack"><?= csrf_field() ?><label class="checkbox-label"><input type="checkbox" name="enabled" value="1" <?= Db::setting('notifications_enabled')==='1' ? 'checked' : '' ?>><span>Show Windows reminders while the application is open</span></label><button class="secondary">Save preference</button></form><p class="footnote">Windows controls notification display and quiet hours. No background service runs after you close the app.</p></section>
